<?php
/** Synthetic SQLite test adapter: two auth tables and optional business tables, never a production activation bypass. */
final class SQLiteAuthDB {
    public $prefix='test_';public $last_error='';public $insert_id=0;public $pdo;private $quiet=false;public $rates=array();public $failNeedle=null;
    public function __construct(){ $this->pdo=new PDO('sqlite::memory:');$this->pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$now="'2026-01-02 12:00:00.123456'";$this->pdo->exec("CREATE TABLE test_sender_suite_users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,email TEXT,display_name TEXT,role TEXT NOT NULL DEFAULT 'admin',is_active INTEGER NOT NULL DEFAULT 1,last_login TEXT,created_at TEXT NOT NULL DEFAULT ".$now.",updated_at TEXT NOT NULL DEFAULT ".$now.")");$this->pdo->exec("CREATE TABLE test_sender_suite_system_settings(id INTEGER PRIMARY KEY AUTOINCREMENT,`key` TEXT UNIQUE NOT NULL,value TEXT,category TEXT NOT NULL DEFAULT 'general',description TEXT,created_at TEXT NOT NULL DEFAULT ".$now.",updated_at TEXT NOT NULL DEFAULT ".$now.")"); }
    public function addTables(array $names){
        $models=json_decode(file_get_contents(__DIR__.'/../sender-suite/schema/models.json'),true,512,JSON_THROW_ON_ERROR);
        foreach($names as $name){$parts=array();foreach($models[$name]['columns'] as $key=>$column){$sql='"'.$key.'" ';if($column['auto_increment']){$sql.='INTEGER PRIMARY KEY AUTOINCREMENT';}else{$sql.=in_array($column['type'],array('Integer','Boolean'),true)?'INTEGER':'TEXT';if(!$column['nullable']){$sql.=' NOT NULL';}}$parts[]=$sql;}$this->pdo->exec('CREATE TABLE "test_sender_suite_'.$name.'" ('.implode(',',$parts).')');}
        if(in_array('contacts',$names,true)){$this->pdo->exec('CREATE UNIQUE INDEX contact_phone ON test_sender_suite_contacts(phone_number)');}
        if(in_array('tags',$names,true)){$this->pdo->exec('CREATE UNIQUE INDEX tag_name ON test_sender_suite_tags(name)');}
        if(in_array('contact_list_members',$names,true)){$this->pdo->exec('CREATE UNIQUE INDEX list_member ON test_sender_suite_contact_list_members(list_id,contact_id)');}
    }
    public function suppress_errors($v){$old=$this->quiet;$this->quiet=$v;return $old;}
    public function prepare($sql,$args){$i=0;$r=preg_replace_callback('/%[sd]/',function($m)use(&$i,$args){$v=$args[$i++];return $m[0]==='%d'?(string)(int)$v:$this->pdo->quote((string)$v);},$sql);if($i!==count($args)){throw new RuntimeException('SQL argument mismatch');}return $r;}
    public function query($sql){$this->last_error='';if($this->failNeedle!==null&&strpos($sql,$this->failNeedle)!==false){$this->failNeedle=null;$this->last_error='Synthetic statement failure';return false;}if(strpos($sql,'INSERT INTO `test_sender_suite_rate_limits`')===0){preg_match("/'([a-f0-9]{64})'/",$sql,$m);$this->rates[$m[1]]=($this->rates[$m[1]]??0)+1;return 1;}try{$r=$this->pdo->exec($sql==='START TRANSACTION'?'BEGIN':$sql);$this->insert_id=(int)$this->pdo->lastInsertId();return $r;}catch(PDOException $e){$this->last_error=$e->getMessage();return false;}}
    public function get_results($sql,$mode){$this->last_error='';if(strpos($sql,'SELECT hits,GREATEST(1,CEIL(TIMESTAMPDIFF(MICROSECOND,UTC_TIMESTAMP(6),expires_at)/1000000)) AS retry_after FROM `test_sender_suite_rate_limits`')===0){preg_match("/'([a-f0-9]{64})'/",$sql,$m);return array(array('hits'=>$this->rates[$m[1]]??0,'retry_after'=>60));}try{return $this->pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);}catch(PDOException $e){$this->last_error=$e->getMessage();return null;}}
}
